"""
Redaction module implementing the redaction-contract/1 policy.

Given a record containing a 'secrets' list (each with 'name', 'value',
and optional 'source'), this module replaces every occurrence of a
non-empty raw secret value anywhere inside string fields of the record
with '<redacted:NAME>'. All other data (endpoints, trace ids, path
labels, sha256 digests, bytes, booleans, numbers, nulls, and
{'secret_ref': NAME} objects) is preserved exactly. No rows are
removed, no lists are reordered, and no secret values are hashed.
"""

from typing import Any, Dict, List, Tuple


def _collect_secret_pairs(secrets: Any) -> List[Tuple[str, str]]:
    """Extract (name, value) pairs for non-empty string secret values.

    Sorted by value length descending so overlapping secrets are
    handled correctly (longer values redacted first).
    """
    pairs: List[Tuple[str, str]] = []
    if isinstance(secrets, list):
        for entry in secrets:
            if not isinstance(entry, dict):
                continue
            name = entry.get("name")
            value = entry.get("value")
            if (
                isinstance(name, str)
                and name != ""
                and isinstance(value, str)
                and value != ""
            ):
                pairs.append((name, value))

    # Longer values first to avoid a short secret partially redacting
    # a longer one that contains it as a substring.
    pairs.sort(key=lambda p: len(p[1]), reverse=True)
    return pairs


def _redact_string(s: str, pairs: List[Tuple[str, str]]) -> str:
    for name, value in pairs:
        if value and value in s:
            s = s.replace(value, "<redacted:%s>" % name)
    return s


def _process(value: Any, pairs: List[Tuple[str, str]]) -> Any:
    if isinstance(value, dict):
        new_dict: Dict[str, Any] = {}
        for key in sorted(value.keys()):
            new_dict[key] = _process(value[key], pairs)
        return new_dict
    elif isinstance(value, list):
        return [_process(item, pairs) for item in value]
    elif isinstance(value, str):
        return _redact_string(value, pairs)
    else:
        # bytes, bool, int, float, None, etc. -- preserved exactly.
        return value


def redact_record(record: Dict[str, Any]) -> Dict[str, Any]:
    """Redact raw secret values from `record` per redaction-contract/1."""
    if not isinstance(record, dict):
        raise TypeError("record must be a dict")

    secrets = record.get("secrets", [])
    pairs = _collect_secret_pairs(secrets)

    # Build the new top-level record: copy all existing keys, then set
    # the redaction_policy marker.
    working: Dict[str, Any] = dict(record)
    working["redaction_policy"] = "redaction-contract/1"

    return _process(working, pairs)
