"""
Redaction module implementing the redaction-contract/1 policy.

Given a record containing a 'secrets' list (each with 'name', 'value',
and optional 'source'), this module replaces every occurrence of a
non-empty raw secret value anywhere inside string fields of the record
with '<redacted:NAME>'. Longer secret values are always redacted before
shorter ones so that overlapping secrets never partially clobber each
other. All other data (endpoints, trace ids, path labels, sha256
digests, booleans, numbers, nulls, bytes, and {'secret_ref': NAME}
markers) is preserved exactly as-is.
"""

import re


def _build_matcher(secrets):
    """Build a compiled regex and name lookup for non-empty secret values,
    sorted so that longer values are matched (and thus replaced) first.
    """
    entries = []
    for s in secrets:
        if not isinstance(s, dict):
            continue
        name = s.get("name")
        value = s.get("value")
        if isinstance(value, str) and value != "" and isinstance(name, str):
            entries.append((name, value))

    if not entries:
        return None, []

    # Sort by descending length of the raw value so longer secrets are
    # preferred by the regex engine (which tries alternatives in order).
    entries.sort(key=lambda item: len(item[1]), reverse=True)

    names = [name for name, _ in entries]
    pattern_parts = [
        "(?P<g{0}>{1})".format(i, re.escape(value))
        for i, (_, value) in enumerate(entries)
    ]
    pattern = "|".join(pattern_parts)
    compiled = re.compile(pattern)
    return compiled, names


def _make_replacer(names):
    def _replace(match):
        idx = match.lastindex - 1
        return "<redacted:{0}>".format(names[idx])
    return _replace


def _redact_string(value, compiled, replacer):
    if compiled is None:
        return value
    return compiled.sub(replacer, value)


def _walk(obj, compiled, replacer):
    if isinstance(obj, dict):
        return {k: _walk(v, compiled, replacer) for k, v in obj.items()}
    if isinstance(obj, list):
        return [_walk(v, compiled, replacer) for v in obj]
    if isinstance(obj, str):
        return _redact_string(obj, compiled, replacer)
    # bool, int, float, None, bytes, and any other JSON-like scalars
    # are preserved exactly as-is.
    return obj


def redact_record(record):
    """
    Redact raw secret values from `record` according to
    redaction-contract/1.

    :param record: a JSON-like dict containing a 'secrets' list.
    :return: a new JSON-serializable dict with raw secret values
             replaced by '<redacted:NAME>' references, and
             'redaction_policy' set to 'redaction-contract/1'.
    """
    if not isinstance(record, dict):
        raise TypeError("redact_record expects a dict")

    secrets = record.get("secrets", [])
    if not isinstance(secrets, list):
        secrets = []

    compiled, names = _build_matcher(secrets)
    replacer = _make_replacer(names) if compiled is not None else None

    result = _walk(record, compiled, replacer)

    if not isinstance(result, dict):
        # Should not happen since record is a dict, but keep contract safe.
        result = {}

    result["redaction_policy"] = "redaction-contract/1"

    return result
