"""Redaction module implementing redaction-contract/1.

Given a JSON-like record containing a `secrets` list of
{name, value, source} entries, replace every non-empty raw secret
`value` occurrence within any string in the record (including inside
the `secrets` list itself) with `<redacted:NAME>`.

No network calls, file reads, credentials, or environment access are
used; this module only operates on the data passed to it.
"""

from typing import Any, List, Tuple


def _collect_secrets(record: Any) -> List[Tuple[str, str]]:
    """Extract (name, value) pairs for non-empty secret values.

    Longer values are ordered first so that overlapping secrets don't
    partially redact each other.
    """
    pairs: List[Tuple[str, str]] = []
    secrets = record.get("secrets") if isinstance(record, dict) else None
    if isinstance(secrets, list):
        for entry in secrets:
            if not isinstance(entry, dict):
                continue
            name = entry.get("name")
            value = entry.get("value")
            if isinstance(name, str) and isinstance(value, str) and value != "":
                pairs.append((name, value))

    # Sort by length of raw value, descending, so longer secrets are
    # substituted first (prevents short secrets from partially
    # redacting longer ones that contain them as substrings).
    pairs.sort(key=lambda nv: len(nv[1]), reverse=True)
    return pairs


def _redact_string(s: str, pairs: List[Tuple[str, str]]) -> str:
    for name, value in pairs:
        if value in s:
            s = s.replace(value, "<redacted:%s>" % name)
    return s


def _redact_value(value: Any, pairs: List[Tuple[str, str]]) -> Any:
    if isinstance(value, str):
        return _redact_string(value, pairs)
    if isinstance(value, dict):
        return {k: _redact_value(v, pairs) for k, v in value.items()}
    if isinstance(value, list):
        return [_redact_value(v, pairs) for v in value]
    if isinstance(value, tuple):
        return [_redact_value(v, pairs) for v in value]
    # bytes, bool, int, float, None, and anything else pass through
    # unchanged.
    return value


def redact_record(record: dict) -> dict:
    """Redact raw secret values from `record` per redaction-contract/1."""
    if not isinstance(record, dict):
        raise TypeError("record must be a dict")

    pairs = _collect_secrets(record)

    redacted = _redact_value(record, pairs)
    if not isinstance(redacted, dict):
        redacted = {}

    redacted["redaction_policy"] = "redaction-contract/1"
    return redacted
