"""
Redaction module implementing redaction-contract/1.

Given a JSON-like record containing a 'secrets' list (each with 'name',
'value', and optional 'source'), replace every occurrence of each secret's
raw value anywhere within string fields of the record with
'<redacted:NAME>'. Longer secret values are replaced before shorter ones so
overlapping/prefix secrets don't cause partial redactions.
"""

from copy import deepcopy


def redact_record(record):
    """
    Redact secret values found anywhere in `record`'s string fields.

    :param record: dict, JSON-like input containing a 'secrets' list.
    :return: new dict, JSON-serializable, with secrets redacted and
             'redaction_policy' set to 'redaction-contract/1'.
    """
    secrets = record.get('secrets', []) if isinstance(record, dict) else []

    # Build (value, name) pairs for non-empty secret values.
    replacements = []
    if isinstance(secrets, list):
        for entry in secrets:
            if not isinstance(entry, dict):
                continue
            name = entry.get('name')
            value = entry.get('value')
            if isinstance(value, str) and value != '' and isinstance(name, str):
                replacements.append((value, name))

    # Longer values first, so overlapping/prefix secrets are handled correctly.
    replacements.sort(key=lambda pair: len(pair[0]), reverse=True)

    def replace_in_string(s):
        for value, name in replacements:
            if value and value in s:
                s = s.replace(value, "<redacted:%s>" % name)
        return s

    def walk(obj):
        if isinstance(obj, dict):
            return {k: walk(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [walk(v) for v in obj]
        elif isinstance(obj, str):
            return replace_in_string(obj)
        else:
            # numbers, booleans, None, bytes, etc. -- preserve exactly
            return obj

    new_record = walk(deepcopy(record)) if isinstance(record, dict) else deepcopy(record)

    if isinstance(new_record, dict):
        new_record['redaction_policy'] = 'redaction-contract/1'

    return new_record
