"""Redaction module implementing redaction-contract/1.

Given a JSON-like record containing a `secrets` list (each secret dict having
`name`, `value`, and optional `source`), replace every occurrence of a
non-empty secret's raw `value` anywhere within any string in the record with
`<redacted:NAME>`. Longer secret values are redacted before shorter ones so
that overlapping secrets never partially clobber each other. All other data
(numbers, booleans, null, bytes, sha256 digests, path labels, endpoints,
trace ids, `{'secret_ref': NAME}` markers, list ordering, and dict keys) is
preserved exactly. The returned dict always includes
`redaction_policy: "redaction-contract/1"`.
"""

from typing import Any, List, Tuple


def _collect_secret_pairs(record: dict) -> List[Tuple[str, str]]:
    """Extract (name, value) pairs for non-empty string secret values.

    Sorted by descending value length so longer secrets are substituted
    first, preventing a shorter secret from partially matching inside a
    longer one.
    """
    pairs: List[Tuple[str, str]] = []
    secrets = record.get("secrets")
    if isinstance(secrets, list):
        for entry in secrets:
            if not isinstance(entry, dict):
                continue
            name = entry.get("name")
            value = entry.get("value")
            if isinstance(name, str) and isinstance(value, str) and value:
                pairs.append((name, value))

    # Longest raw value first; stable sort preserves original relative order
    # for equal-length values.
    pairs.sort(key=lambda p: len(p[1]), reverse=True)
    return pairs


def _redact_string(s: str, pairs: List[Tuple[str, str]]) -> str:
    for name, value in pairs:
        if value and value in s:
            s = s.replace(value, "<redacted:{}>".format(name))
    return s


def _redact_value(value: Any, pairs: List[Tuple[str, str]]) -> Any:
    if isinstance(value, str):
        return _redact_string(value, pairs)
    if isinstance(value, dict):
        return {k: _redact_value(v, pairs) for k, v in value.items()}
    if isinstance(value, list):
        return [_redact_value(v, pairs) for v in value]
    if isinstance(value, tuple):
        return tuple(_redact_value(v, pairs) for v in value)
    # Numbers, booleans, None, bytes, and any other opaque types pass through
    # unchanged.
    return value


def redact_record(record: dict) -> dict:
    """Redact all raw secret values from `record` per redaction-contract/1."""
    if not isinstance(record, dict):
        raise TypeError("record must be a dict")

    pairs = _collect_secret_pairs(record)

    redacted = _redact_value(record, pairs)

    if not isinstance(redacted, dict):
        # record was a dict, so _redact_value on a dict always returns dict.
        redacted = dict(redacted)

    redacted["redaction_policy"] = "redaction-contract/1"

